// 1. Initialize Mother App (for Auth and Super Admin registry)
export const motherApp = getApps().find(a => a.name === "[DEFAULT]") || initializeApp(motherFirebaseConfig);
export const motherDatabase = getDatabase(motherApp);
export const auth = getAuth(motherApp);

// 2. Active Tenant Database (Default starts at motherDatabase or fallback ecatramble003)
let currentDatabase: Database = motherDatabase;
const customAppInstances = new Map<string, FirebaseApp>();

export function connectToDedicatedFirebase(config: FirebaseOptions | string, appName: string): Database {
  try {
    const finalConfig: FirebaseOptions = typeof config === "string"
      ? { ...motherFirebaseConfig, databaseURL: config.trim().replace(/\/$/, "") }
      : { ...motherFirebaseConfig, ...config, databaseURL: (config.databaseURL || "").trim().replace(/\/$/, "") };

    let app: FirebaseApp;
    if (customAppInstances.has(appName)) {
      app = customAppInstances.get(appName)!;
    } else {
      const existing = getApps().find(a => a.name === appName);
      app = existing || initializeApp(finalConfig, appName);
      customAppInstances.set(appName, app);
    }
    const db = getDatabase(app);
    currentDatabase = db;
    updateRefs(db);
    console.log(`🔌 Connected to Dedicated Firebase for ${appName}:`, finalConfig.databaseURL);
    return db;
  } catch (err) {
    console.error("Failed to connect to dedicated Firebase:", err);
    return currentDatabase;
  }
}

// Transparent Proxy wrapper so all components importing `database` automatically use the active tenant DB
export const database: Database = new Proxy({} as Database, {
  get(_, prop) {
    return (currentDatabase as any)[prop];
  }
});

// Dynamic refs that automatically update on tenant switch
export let rootRef = ref(currentDatabase, "/");
export let cookedRef = ref(currentDatabase, "kitchen_cooked_items");
export let deliveredRef = ref(currentDatabase, "delivered_orders");
export let undeliveredRef = ref(currentDatabase, "undelivered_orders");
export let receivedPaymentsRef = ref(currentDatabase, "admin_received_payments");
export let lossOrdersRef = ref(currentDatabase, "admin_loss_orders");

export function updateRefs(db: Database) {
  rootRef = ref(db, "/");
  cookedRef = ref(db, "kitchen_cooked_items");
  deliveredRef = ref(db, "delivered_orders");
  undeliveredRef = ref(db, "undelivered_orders");
  receivedPaymentsRef = ref(db, "admin_received_payments");
  lossOrdersRef = ref(db, "admin_loss_orders");
}
